code.C:
#include <stdio.h>
#include <string.h>
#include <ctype.h>
int main() {
    char s[2000]; if (!fgets(s, sizeof(s), stdin)) return 0;
    int seen[26] = {0}, cnt = 0;
    for (int i = 0; s[i]; i++) {
        if (isalpha(s[i])) {
            int idx = tolower(s[i]) - 'a';
            if (!seen[idx]) { seen[idx] = 1; cnt++; }
        }
    }
    puts(cnt == 26 ? "Yes" : "No");
    return 0;
}

code.C++:
#include <iostream>
#include <string>
#include <unordered_set>
#include <cctype>
using namespace std;
int main() {
    string s; if (!getline(cin, s)) return 0;
    unordered_set<char> st;
    for (char c : s) if (isalpha(c)) st.insert(tolower(c));
    cout << (st.size() == 26 ? "Yes" : "No") << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.HashSet;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String s = sc.nextLine().toLowerCase();
            HashSet<Character> st = new HashSet<>();
            for (char c : s.toCharArray()) if (c >= 'a' && c <= 'z') st.add(c);
            System.out.println(st.size() == 26 ? "Yes" : "No");
        }
    }
}

